// ============================================================================
// DIGITAL CLONE - VOICE AND AVATAR RENDER - CONFIG
// Milestone 1 of the brief: ElevenLabs audio output driving HeyGen avatar
// synthesis. Workflow 01 hands work to this one; it can also be called directly.
//
// Blank key -> that step is SKIPPED, never a failed run.
// ============================================================================

// ---------------------------------------------------------------- Safety
// Ships in PREVIEW: the audio and the video are produced, but nothing is
// delivered to the requester. Read STOP: preview - not delivered first.
const DRY_RUN = true;

// ---------------------------------------------------------------- ElevenLabs
const ELEVENLABS_API_KEY  = '';                       // blank -> nothing is synthesised
const ELEVENLABS_BASE_URL = 'https://api.elevenlabs.io';
const ELEVENLABS_VOICE_ID = '';                       // your cloned voice id
const ELEVENLABS_MODEL    = 'eleven_turbo_v2_5';      // turbo: lowest latency
const VOICE_SETTINGS      = { stability: 0.5, similarity_boost: 0.75 };

// The brief asks for latency to be measured. Every stage stamps its own
// duration and the summary prints them; this is the budget it compares against.
const LATENCY_BUDGET_MS = { speech: 6000, render: 180000 };

// ---------------------------------------------------------------- HeyGen
const HEYGEN_API_KEY   = '';                          // blank -> audio only, no video
const HEYGEN_BASE_URL  = 'https://api.heygen.com';
const HEYGEN_AVATAR_ID = '';                          // your avatar id
const HEYGEN_DIMENSION = { width: 1280, height: 720 };

// A render is asynchronous. These bound the wait so a stuck job fails loudly
// instead of holding an execution open forever.
const POLL_SECONDS  = 10;
const POLL_MAX_TRIES = 18;        // 18 x 10s = 3 minutes, then it gives up

// Where the finished audio/video is sent. Blank -> produced and logged only.
const DELIVERY_WEBHOOK_URL = '';

// A public URL for the synthesised audio. HeyGen fetches the audio rather than
// receiving the bytes, so it must be reachable from the internet. Leave blank
// and the workflow uses HeyGen's own text-to-speech instead of the clone voice -
// which is a real downgrade, and the summary says so rather than hiding it.
const AUDIO_PUBLIC_BASE_URL = '';

// ============================================================================
return [{ json: {
  DRY_RUN,
  ELEVENLABS_API_KEY, ELEVENLABS_BASE_URL, ELEVENLABS_VOICE_ID, ELEVENLABS_MODEL,
  VOICE_SETTINGS, LATENCY_BUDGET_MS,
  HEYGEN_API_KEY, HEYGEN_BASE_URL, HEYGEN_AVATAR_ID, HEYGEN_DIMENSION,
  POLL_SECONDS, POLL_MAX_TRIES,
  DELIVERY_WEBHOOK_URL, AUDIO_PUBLIC_BASE_URL,
  voice_enabled:    ELEVENLABS_API_KEY.length > 0 && ELEVENLABS_VOICE_ID.length > 0,
  avatar_enabled:   HEYGEN_API_KEY.length > 0 && HEYGEN_AVATAR_ID.length > 0,
  delivery_enabled: DELIVERY_WEBHOOK_URL.length > 0,
  audio_hosted:     AUDIO_PUBLIC_BASE_URL.length > 0,
} }];

// One shape, whether this came from workflow 01, a direct call, or the demo button.
const SAMPLE = {
  request_id: 'demo-001',
  mode: 'video',
  script: 'Hi Jordan - happy to find a time. You can grab a slot on my calendar and I will confirm in the morning.',
  reply_to: 'jordan.blake@example.com',
};

const src = $input.first().json || {};
const body = src.body && typeof src.body === 'object' ? src.body : src;

const script = (body.script || body.text || SAMPLE.script).toString().trim();
const mode = ['voice', 'video'].includes(body.mode) ? body.mode : SAMPLE.mode;

// ElevenLabs bills per character. A runaway script is the expensive failure here,
// so it is refused rather than truncated - a half-sentence reply is worse than none.
const MAX_CHARS = 1200;

return [{ json: {
  request_id: body.request_id || SAMPLE.request_id,
  reply_to: body.reply_to || SAMPLE.reply_to,
  mode,
  script,
  chars: script.length,
  too_long: script.length > MAX_CHARS,
  usable: script.length > 0 && script.length <= MAX_CHARS,
  started_at: Date.now(),
} }];

// Empty, or over the character cap. ElevenLabs bills per character, so a runaway script is refused rather than truncated.
const r = $input.first().json;
return [{ json: { stopped_at: 'script rejected', reason: `Empty, or over the character cap. ElevenLabs bills per character, so a runaway script is refused rather than truncated.`, request: r } }];

// No API key or no voice id. Nothing was synthesised and nothing was charged.
const r = $input.first().json;
return [{ json: { stopped_at: 'ElevenLabs not configured', reason: `No API key or no voice id. Nothing was synthesised and nothing was charged.`, request: r } }];

// Prove the bytes are really audio before anything downstream trusts them.
// A 200 with an error body is the normal way a TTS call fails, and an "audio"
// file that is actually JSON is the thing that breaks the avatar render with
// an unreadable message two nodes later.
const cfg = $('config').first().json;
const r = $('read the render request').first().json;
const item = $input.first();
const bin = item.binary && (item.binary.data || Object.values(item.binary)[0]);

const size = bin ? Number(bin.fileSize || 0) || (bin.data ? Buffer.from(bin.data, 'base64').length : 0) : 0;
const mime = bin ? (bin.mimeType || '') : '';
const looks_audio = /audio|mpeg|mp3|wav/i.test(mime) && size > 1024;

const elapsed = Date.now() - r.started_at;

return [{
  json: {
    ...r,
    audio_bytes: size,
    audio_mime: mime,
    audio_ok: looks_audio,
    speech_ms: elapsed,
    speech_over_budget: elapsed > cfg.LATENCY_BUDGET_MS.speech,
    audio_reason: looks_audio ? 'ok'
      : (size === 0 ? 'no audio returned' : `unexpected content type "${mime}" (${size} bytes)`),
  },
  binary: item.binary,
}];

// The TTS call returned something that is not audio. A 200 with an error body is the normal way this fails.
const r = $input.first().json;
return [{ json: { stopped_at: 'no usable audio', reason: `The TTS call returned something that is not audio. A 200 with an error body is the normal way this fails.`, request: r } }];

// mode = voice. The audio is the finished article; no avatar render is needed.
const r = $input.first().json;
return [{ json: { ...r, deliverable: 'audio', succeeded: true } }];

// No API key or no avatar id, so the video half is skipped. The audio still exists.
const r = $input.first().json;
return [{ json: { stopped_at: 'HeyGen not configured', reason: `No API key or no avatar id, so the video half is skipped. The audio still exists.`, request: r } }];

// Read HeyGen's acknowledgement. It returns a job id, not a video - the render
// happens on their side and we poll for it below.
const r = $('check the audio').first().json;
const res = $input.first().json || {};
const id = res?.data?.video_id || res?.video_id || null;

return [{ json: {
  ...r,
  video_id: id,
  render_started_at: Date.now(),
  tries: 0,
  accepted: Boolean(id),
  accept_reason: id ? 'accepted' : `HeyGen did not return a video id: ${JSON.stringify(res).slice(0, 300)}`,
} }];

// HeyGen did not return a video id, so there is nothing to poll for.
const r = $input.first().json;
return [{ json: { stopped_at: 'render not accepted', reason: `HeyGen did not return a video id, so there is nothing to poll for.`, request: r } }];

// One poll. Counts its own attempts so the loop is bounded by config rather
// than by hope, and carries the elapsed time so the summary can report latency.
const cfg = $('config').first().json;
const prev = $('read the render job').first().json;
const seen = $input.first().json || {};

const st = (seen?.data?.status || seen?.status || 'unknown').toLowerCase();
const tries = Number($runIndex || 0) + 1;
const elapsed = Date.now() - prev.render_started_at;

const done = ['completed', 'failed', 'error'].includes(st);
const ok = st === 'completed';

return [{ json: {
  ...prev,
  tries,
  status: st,
  finished: done || tries >= cfg.POLL_MAX_TRIES,
  succeeded: ok,
  timed_out: !done && tries >= cfg.POLL_MAX_TRIES,
  render_ms: elapsed,
  render_over_budget: elapsed > cfg.LATENCY_BUDGET_MS.render,
  video_url: seen?.data?.video_url || seen?.video_url || null,
  render_reason: ok ? 'completed'
    : (!done && tries >= cfg.POLL_MAX_TRIES
        ? `gave up after ${tries} polls (${Math.round(elapsed / 1000)}s)`
        : `HeyGen reported "${st}"`),
} }];

// HeyGen reported a failure, or the poll gave up. The reason and the elapsed time are on the item.
const r = $input.first().json;
return [{ json: { stopped_at: 'render failed', reason: `HeyGen reported a failure, or the poll gave up. The reason and the elapsed time are on the item.`, request: r } }];

// DRY_RUN is true, or no delivery URL is set. The audio and video were produced - nothing was sent.
const r = $input.first().json;
return [{ json: { stopped_at: 'preview - not delivered', reason: `DRY_RUN is true, or no delivery URL is set. The audio and video were produced - nothing was sent.`, request: r } }];

// The latency report the brief asks for, plus the outcome. This is the node to
// open after any run - preview or live.
const cfg = $('config').first().json;
const r = $input.first().json;
const s = (ms) => ms === undefined || ms === null ? '-' : `${Math.round(ms)}ms`;

const lines = [
  `Clone render - ${r.request_id || 'no id'}  [${r.mode || '-'}]`,
  `  script      ${r.chars ?? '-'} chars`,
  `  speech      ${s(r.speech_ms)}   budget ${cfg.LATENCY_BUDGET_MS.speech}ms${r.speech_over_budget ? '   OVER' : ''}`,
];
if (r.mode === 'video') {
  lines.push(`  render      ${s(r.render_ms)}   budget ${cfg.LATENCY_BUDGET_MS.render}ms${r.render_over_budget ? '   OVER' : ''}`);
  lines.push(`  polls       ${r.tries ?? '-'} of ${cfg.POLL_MAX_TRIES}`);
  lines.push(`  status      ${r.status || '-'}  ${r.render_reason || ''}`);
  if (!cfg.audio_hosted) {
    lines.push(`  NOTE        AUDIO_PUBLIC_BASE_URL is blank, so HeyGen used its own voice,`);
    lines.push(`              not the ElevenLabs clone. Set it to use the cloned voice.`);
  }
}
lines.push(`  delivered   ${cfg.DRY_RUN ? 'no  (DRY_RUN)' : (cfg.delivery_enabled ? 'yes' : 'no  (no delivery URL)')}`);

return [{ json: { text: lines.join('\n'), ...r } }];
